#!/bin/bash
# ---------------------------------------------------------------------------
# Poetry pin drift check.
#
#   bash .github/scripts/check-poetry-pin-drift.sh
#
# backend/poetry.lock is written by one Poetry and read by several: the two
# image builds export it to requirements.txt, CI and the deploy workflow install
# from it, and the AFK sandbox image installs the same toolchain. Every one of
# those pins an exact version, and nothing has ever compared those pins against
# the lock they read.
#
#   exit 0  every pin can read the lock, and the pins agree
#   exit 1  drift
#   exit 2  the check could not run
#
# The rule is `pin >= the version that wrote the lock`, taken from the header
# Poetry stamps into the file itself. That is deliberately coarser than Poetry's
# real compatibility rule, which is keyed on `lock-version` rather than on the
# generator. Encoding the lock-version-to-Poetry-version table here would mean
# maintaining a copy of Poetry's release history in a shell script and getting it
# wrong quietly; "a newer Poetry can always read what an older one wrote" needs
# no table and errs toward refusing a pin that would in fact have worked.
#
# Why this is not merely a style check: a pin BELOW the writer does not
# necessarily fail. Poetry 1.8.3 reads this 2.1 lock, prints "The lock file might
# not be compatible with the current version of Poetry", and exits 0 with a
# correct export — which is how five pins sat two majors behind the lock without
# anyone noticing (#153). The warning goes into build logs nobody reads. The next
# lock-version bump turns it into a hard failure at every pin at once.
#
# Tested by .github/scripts/test-poetry-pin-drift.sh (`make test-poetry-pin`).
# A check that has never once failed is indistinguishable from one that cannot.
# ---------------------------------------------------------------------------
set -uo pipefail

ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)
cd "$ROOT" || exit 2

LOCK="backend/poetry.lock"
[ -f "$LOCK" ] || { echo "Cannot find $LOCK from $ROOT." >&2; exit 2; }

# The writer. Poetry stamps its own version into the first line.
writer=$(sed -n '1s/.*@generated by Poetry \([0-9][0-9.]*[0-9]\).*/\1/p' "$LOCK")
lockver=$(sed -n 's/^lock-version = "\([^"]*\)".*/\1/p' "$LOCK" | head -1)
if [ -z "$writer" ]; then
  echo "Could not read the generator version from the header of $LOCK." >&2
  echo "Expected line 1 to read: # This file is automatically @generated by Poetry X.Y.Z ..." >&2
  exit 2
fi

# The readers. Tracked files only, so an untracked scratch Dockerfile cannot
# fail the build. `.github/scripts` is excluded because this check and its test
# both have to write the string `poetry==` to talk about it at all.
pins=$(git grep -nE 'poetry==[0-9]+\.[0-9]+(\.[0-9]+)?' -- . ':(exclude).github/scripts' 2>/dev/null)

if [ -z "$pins" ]; then
  echo "No pinned Poetry versions found. The check has lost its subject — either" >&2
  echo "the pins moved somewhere git grep does not see, or the pattern went stale." >&2
  exit 2
fi

# `pin >= want`, numerically per component rather than lexically: 1.10.0 is newer
# than 1.9.0, and a string compare says the opposite.
vge() { [ "$(printf '%s\n%s\n' "$2" "$1" | sort -V | head -1)" = "$2" ]; }

behind=""      # pins that cannot read the lock
disagree=""    # pins that do not match the majority
missing=""     # `poetry export` on Poetry 2.x without the plugin
seen=""

while IFS= read -r hit; do
  [ -z "$hit" ] && continue
  file=${hit%%:*}
  rest=${hit#*:}
  line=${rest%%:*}
  ver=$(printf '%s' "$hit" | sed -n 's/.*poetry==\([0-9][0-9.]*[0-9]\).*/\1/p')
  [ -z "$ver" ] && continue

  seen="$seen$ver
"
  vge "$ver" "$writer" || behind="$behind  $file:$line  pins poetry==$ver
"

  # Poetry 2.x unbundled `poetry export` into poetry-plugin-export. A file that
  # runs the command and installs 2.x without the plugin builds a stage that
  # dies on "The command \"export\" does not exist" — the trap #153 named.
  if vge "$ver" "2.0.0" && grep -q 'poetry export' "$file" 2>/dev/null \
     && ! grep -q 'poetry-plugin-export' "$file" 2>/dev/null; then
    missing="$missing  $file  runs 'poetry export' on poetry==$ver without poetry-plugin-export
"
  fi
done <<<"$pins"

# One version everywhere. Without this you fix the Dockerfile that broke and
# leave the workflow that did not — which is the shape #153 actually had.
agreed=$(printf '%s' "$seen" | sort | uniq -c | sort -rn | head -1 | awk '{print $2}')
while IFS= read -r hit; do
  [ -z "$hit" ] && continue
  file=${hit%%:*}
  rest=${hit#*:}
  line=${rest%%:*}
  ver=$(printf '%s' "$hit" | sed -n 's/.*poetry==\([0-9][0-9.]*[0-9]\).*/\1/p')
  [ -z "$ver" ] && continue
  [ "$ver" = "$agreed" ] || disagree="$disagree  $file:$line  pins poetry==$ver, but $agreed is pinned elsewhere
"
done <<<"$pins"

count=$(printf '%s' "$seen" | grep -c .)

if [ -z "$behind" ] && [ -z "$disagree" ] && [ -z "$missing" ]; then
  echo "OK — $count pins, all poetry==$agreed, all able to read $LOCK (written by Poetry $writer, lock-version $lockver)."
  exit 0
fi

# ---------------------------------------------------------------------------
# Drift. Name every site and say what to run: a failure that does not tell you
# how to fix it is one that gets worked around.
# ---------------------------------------------------------------------------
if [ -n "${GITHUB_ACTIONS:-}" ]; then
  echo "::error title=Poetry pin drift::A pinned Poetry disagrees with $LOCK (written by Poetry $writer). See the job log for every site."
fi

cat >&2 <<EOF

────────────────────────────────────────────────────────────────────────────
  POETRY PIN DRIFT
────────────────────────────────────────────────────────────────────────────

  $LOCK was written by Poetry $writer (lock-version $lockver).

EOF

if [ -n "$behind" ]; then
  cat >&2 <<EOF
  These pins are older than the Poetry that wrote the lock:

$behind
  Poetry may still read it and merely warn — which is why this went unseen —
  but the next lock-version bump makes it a hard failure at every site above.

EOF
fi

if [ -n "$disagree" ]; then
  cat >&2 <<EOF
  These pins disagree with each other:

$disagree
EOF
fi

if [ -n "$missing" ]; then
  cat >&2 <<EOF
  Poetry 2.x no longer bundles the export command:

$missing
  Add poetry-plugin-export to the same install line.

EOF
fi

cat >&2 <<EOF
  Fix — set every pin to the version that writes the lock:

      git grep -nE 'poetry==[0-9]' -- . ':(exclude).github/scripts'

  and if you meant to move Poetry instead, regenerate the lock with the version
  you want and bump the pins to match it in the same commit.

────────────────────────────────────────────────────────────────────────────
EOF

exit 1
